package com.aicharacter.v3;
/** Converts real landing/impact energy into body consequences. No random injury events. */
public final class ImpactEngine{private ImpactEngine(){}
 public static void land(WorldState s,String actor,double verticalSpeed,long now){if(s==null||verticalSpeed<=0)return;PhysicsBodyState p="cat".equals(actor)?s.catPhysics:s.girlPhysics;if(p==null)return;double verticalEnergy=.5*p.massKg*verticalSpeed*verticalSpeed,bodyFallEnergy=p.massKg*WholeBodyPhysicsEngine.GRAVITY*p.fallBodyHeightM,horizontalEnergy=.5*p.massKg*p.velocityX*p.velocityX,energy=Math.max(verticalEnergy,bodyFallEnergy)+horizontalEnergy*.22;double armTransfer=0,headAvoidance=0,braceDissipation=0;if("girl".equals(actor)&&s.nervous!=null){armTransfer=Math.min(.24,s.nervous.armProtection*.24);headAvoidance=Math.min(.20,s.nervous.headProtection*.20);braceDissipation=Math.min(.22,s.nervous.fallBrace*.22);}double protectedFraction=Math.min(.52,armTransfer+headAvoidance+braceDissipation),effectiveEnergy=energy*(1-protectedFraction);double tolerance="cat".equals(actor)?85:260;double excess=Math.max(0,effectiveEnergy-tolerance);double residualHorizontal=Math.abs(p.velocityX),loadAsymmetry="girl".equals(actor)&&s.bodyRig!=null?Math.abs(s.bodyRig.leftLegLoad-s.bodyRig.rightLegLoad):0;p.landingInstability=Math.min(1,residualHorizontal/2.4+verticalSpeed/8.5+loadAsymmetry*.42+(1-p.traction)*.28);p.centerOfMassX+=Math.signum(p.velocityX)*p.landingInstability*.16;p.velocityY=0;p.velocityX*=Math.max(.08,1-Math.min(.88,effectiveEnergy/900.0));p.grounded=true;p.falling=false;p.groundReaction=p.massKg*WholeBodyPhysicsEngine.GRAVITY+Math.min(p.massKg*WholeBodyPhysicsEngine.GRAVITY*5,effectiveEnergy*.18);if(excess<=0)return;if("girl".equals(actor)){if(s.musculoskeletal!=null)s.musculoskeletal.impactLoad=Math.min(20,s.musculoskeletal.impactLoad+excess/120.0);double ll=s.bodyRig==null?.5:s.bodyRig.leftLegLoad,rl=s.bodyRig==null?.5:s.bodyRig.rightLegLoad,armContactEnergy=energy*armTransfer,headContactEnergy=energy*Math.max(0,.18-headAvoidance*.72);PainLocalizationEngine.addLandingImpact(s,excess,ll,rl,Math.min(1,armContactEnergy/220.0),Math.min(1,headContactEnergy/180.0),now);SystemicHomeostasisEngine.registerImpact(s,excess,now);if(s.musculoskeletal!=null){s.musculoskeletal.armForceCapacity=Math.max(.25,s.musculoskeletal.armForceCapacity-Math.min(.16,armContactEnergy/1800.0));s.musculoskeletal.coreFatigue=Math.min(1,s.musculoskeletal.coreFatigue+Math.min(.12,braceDissipation*energy/2200.0));}double pain=Math.min(34,excess/55.0);s.body.pain=Math.min(100,s.body.pain+pain);s.body.health=Math.max(0,s.body.health-Math.min(12,excess/240.0));if(pain>8&& !s.body.hasInjury())s.body.injury="impact strain";s.body.clamp();}else{s.catState.energy=Math.max(0,s.catState.energy-Math.min(18,excess/35.0));}WorldEventBus.publish(s,now,"PHYSICAL_IMPACT","impact_"+actor+"_"+now,actor+" had a physical landing impact.");}
}